package server

import (
	"context"
	"encoding/json"
	"io"
	"net"
	"net/http"
	"net/http/httputil"
	"net/url"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

type engineStartFault struct {
	Armed     atomic.Bool
	Denied    atomic.Int32
	Phase     atomic.Int32
	Observed  atomic.Bool
	Stack     string
	Container atomic.Value
	Request   atomic.Value
	Attempts  atomic.Int32
	Known     sync.Map
}

// Deny only starts for the explicitly selected synthetic stack. All target
// deployment receipts remain generated by actual Dill, not this engine relay.
func newEngineStartFault(t *testing.T, socket, dir, stack string) (string, *engineStartFault) {
	t.Helper()
	fault := &engineStartFault{Stack: stack}
	transport := &http.Transport{Proxy: nil, DialContext: func(ctx context.Context, _, _ string) (net.Conn, error) {
		return (&net.Dialer{}).DialContext(ctx, "unix", socket)
	}}
	client := &http.Client{Transport: transport, Timeout: 5 * time.Second}
	u, _ := url.Parse("http://docker")
	proxy := httputil.NewSingleHostReverseProxy(u)
	proxy.Transport = transport
	listener, e := net.Listen("unix", filepath.Join(dir, "engine.sock"))
	if e != nil {
		t.Fatal(e)
	}
	if e = os.Chmod(listener.Addr().String(), 0600); e != nil {
		t.Fatal(e)
	}
	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method == "POST" && strings.HasSuffix(r.URL.Path, "/start") && strings.Contains(r.URL.Path, "/containers/") {
			parts := strings.Split(r.URL.Path, "/containers/")
			id := strings.TrimSuffix(parts[len(parts)-1], "/start")
			if regexp.MustCompile(`^[a-f0-9]{64}$`).MatchString(id) {
				_, known := fault.Known.Load(id)
				res, e := client.Get("http://docker/containers/" + id + "/json")
				if e == nil {
					var item struct {
						Labels map[string]string
						Config struct{ Labels map[string]string }
					}
					b, _ := io.ReadAll(io.LimitReader(res.Body, 1<<20))
					res.Body.Close()
					if res.StatusCode == 200 && json.Unmarshal(b, &item) == nil && item.Config.Labels["dill.stack"] == stack && item.Config.Labels["dill.managed"] == "true" {
						known = true
						fault.Known.Store(id, true)
					}
				}
				if known {
					fault.Attempts.Add(1)
					if fault.Armed.Load() {
						fault.Container.Store(id)
						fault.Denied.Add(1)
						w.Header().Set("Content-Type", "application/json")
						w.WriteHeader(503)
						w.Write([]byte(`{"message":"synthetic engine start outage"}`))
						return
					}
				}
			}
		}
		proxy.ServeHTTP(w, r)
	})
	server := &http.Server{Handler: handler, ReadHeaderTimeout: 5 * time.Second}
	go server.Serve(listener)
	t.Cleanup(func() { server.Close(); transport.CloseIdleConnections() })
	return listener.Addr().String(), fault
}
